import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { RawMaterialInwardService } from '../../services/raw-material-inward-service';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { PurchaseOrder, Invoice } from '../purchase-order/purchase-order';
import { RawMaterial } from '../../models/invoice';
import { Supplier } from '../supplier/supplier';

export interface RawMaterialInward {
  id: number;
  rawMaterialId: number;
  rawMaterial?: RawMaterial;
  supplierId?: number | null;
  supplier?: Supplier | null;
  purchaseOrderId?: number | null;
  po?: PurchaseOrder;
  invoiceId?: number | null;
  invoice?: Invoice | null;
  inwardDate: string;
  bags: number;
  perKg: number;
  grossQty: number;
  purity: number;
  realWt: number;
}
export interface RawMaterialInwardRequest {
   
    purchaseOrderId: number;
    rawMaterialId: number;
    supplierId?: number;
    inwardDate: string;
    bags: number;
    perKg: number;
    grossQty: number;
    purity: number;
    realWt: number;

}

@Component({
  selector: 'app-raw-material-inward',
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './raw-material-inward.html',
  styleUrl: './raw-material-inward.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RawMaterialInwardComponent {
  Inward: RawMaterialInward[] = [];
  searchTerm = '';
  constructor(private service: RawMaterialInwardService, private cd: ChangeDetectorRef, public router: Router) {}

  ngOnInit() {
    this.service.getInwards().subscribe({
      next: (data) => {
        this.Inward = data;
        this.cd.markForCheck();
        console.log("products from backend: ", this.Inward);
      },
      error: (err) => console.error("error fetching inwards: ", err)
    })
  }

FilteredInwards() {
  const term = this.searchTerm.toLowerCase();
  return this.Inward.filter(r =>
    (r.rawMaterial?.name ?? "").toLowerCase().includes(term) ||
    (r.supplier?.name ?? "").toLowerCase().includes(term) ||
    (r.po?.address ?? "").toLowerCase().includes(term) ||
    (r.inwardDate ?? "").toLowerCase().includes(term) ||
    (r.bags ?? "").toString().toLowerCase().includes(term) ||
    (r.perKg ?? "").toString().toLowerCase().includes(term) ||
    (r.grossQty?.toString() ?? "").includes(term) ||
    (r.purity?.toString() ?? "").includes(term) ||
    (r.realWt?.toString() ?? "").includes(term)
  );
}

}
